Here's a C++ function that takes a Markdown formatted string and converts it to HTML:

```cpp
#include <iostream>
#include <sstream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    // Convert the Markdown to HTML
    html = std::regex_replace(html, R"## (.*)", R"<h1>$1</h1>");
    html = std::regex_replace(html, R"### (.*)", R"<h2>$1</h2>");
    html = std::regex_replace(html, R"### (.*)", R"<h3>$1</h3>");
    html = std::regex_replace(html, R"### (.*)", R"<h4>$1</h4>");
    html = std::regex_replace(html, R"### (.*)", R"<h5>$1</h5>");
    html = std::regex_replace(html, R"### (.*)", R"<h6>$1</h6>");

    return html;
}
```

This function uses the `std::regex_replace` function to convert the Markdown headers (`##`, `###`, etc.) to their corresponding HTML tags. You can modify the regular expressions to handle more complex headers or other Markdown syntax as needed.

